krpano.action:
if (!krpano._purpleHotspotLoop) {
    krpano._purpleHotspotLoop = true;
    var start = Date.now();
    krpano.actions.renderloop(function () {
        var wave = Math.sin((Date.now() - start) * Math.PI * 2 / 3200);
        for (var i = 0; i < krpano.hotspot.count; i++) {
            var hs = krpano.hotspot.getItem(i);
            if (!hs || !hs.enabled) continue;
            if (hs.icon_glow) {
                var iconWave = (wave + 1) / 2;
                var boost = hs.icon_hover === true || hs.icon_hover === 'true';
                var near = boost ? 1 : 0.75 + iconWave * 0.25;
                var outer = boost ? 1 : 0.55 + iconWave * 0.40;
                var nearRadius = boost ? 22 : 12 + iconWave * 8;
                var outerRadius = boost ? 44 : 24 + iconWave * 16;
                hs.dropshadow = '0 0 4 0xEAD9FF 1, 0 0 ' + nearRadius.toFixed(2) + ' 0xB58AFF ' + near.toFixed(3) + ', 0 0 ' + outerRadius.toFixed(2) + ' 0x955CFF ' + outer.toFixed(3);
                continue;
            }
            if (!hs.purple_motion) continue;
            if (hs._purpleBaseOy === undefined) hs._purpleBaseOy = Number(hs.oy) || 0;
            hs.oy = hs._purpleBaseOy + wave * 5;
            var opacity = (0.38 + (wave + 1) * 0.10).toFixed(3);
            hs.dropshadow = '0 0 5 0xB58AFF 0.65, 0 0 14 0x955CFF ' + opacity;
        }
        return true;
    });
}
